text:
{
 "contract_type": "saas",
 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Orchard Data Ltd."],
   "quote": "by and between Northwind Labs, Inc., a Delaware corporation (\"Northwind\"), and Orchard Data Ltd. (\"Orchard\")"
  },
  "counterparty": {
   "value": "Orchard Data Ltd.",
   "quote": "and Orchard Data Ltd. (\"Orchard\")"
  },
  "effective_date": {
   "value": "2025-01-01",
   "quote": "entered into as of 2025-01-01 (the \"Effective Date\")"
  },
  "term_months": {
   "value": 36,
   "quote": "This Agreement will remain in effect for three (3) years from the Effective Date."
  },
  "auto_renewal": {
   "value": true,
   "quote": "Upon expiration of the Initial Term, the Agreement renews automatically for additional twelve-month terms"
  },
  "renewal_notice_days": {
   "value": 60,
   "quote": "to opt out, a Party must notify the other no later than 60 days before the renewal date."
  },
  "governing_law": {
   "value": "Florida",
   "quote": "The laws of the State of Florida govern this Agreement and any dispute arising out of it."
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  },
  "payment_terms_days": {
   "value": 45,
   "quote": "Invoices are due 45 days after the invoice date."
  },
  "contract_value": {
   "value": 48000,
   "quote": "The subscription fee is $48,000 per year, invoiced annually in advance."
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Imogen Carter",
   "email": "imogen.carter@orchard.example",
   "title": "Managing Director",
   "party": "Orchard Data Ltd."
  }
 ],
 "risks": [
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The contract has no termination clause, so Northwind appears locked into the 3-year initial term (about $144,000 in fees) with no right to exit without cause.",
   "quote": "This Agreement will remain in effect for three (3) years from the Effective Date."
  },
  {
   "id": "auto_renewal_opt_out_window",
   "severity": "medium",
   "message": "The agreement renews automatically for 12-month terms unless Northwind gives notice at least 60 days before the renewal date. Missing the window commits Northwind to another year of fees.",
   "quote": "the Agreement renews automatically for additional twelve-month terms; to opt out, a Party must notify the other no later than 60 days before the renewal date."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The agreement has no confidentiality provisions, so Northwind's data and information shared with Orchard have no contractual protection.",
   "quote": "This Agreement constitutes the entire agreement between the Parties and supersedes all prior discussions relating to its subject matter."
  },
  {
   "id": "no_data_protection_terms",
   "severity": "low",
   "message": "There are no data protection or security terms covering the data Northwind puts into the analytics platform.",
   "quote": "Orchard provides a software as a service analytics platform and Northwind wishes to subscribe."
  },
  {
   "id": "mismatched_provider_term",
   "severity": "low",
   "message": "The SLA refers to 'Provider' and 'Service', which are not defined terms. It also states no remedy for missed uptime, so the 99.9% commitment may be hard to enforce.",
   "quote": "Provider will make the Service available with 99.9% monthly uptime, excluding scheduled maintenance."
  },
  {
   "id": "foreign_counterparty_florida_law",
   "severity": "low",
   "message": "Florida law governs while Northwind is a Delaware company and the counterparty looks to be a non-US entity (Ltd.). There is no venue or forum clause, which could complicate enforcement.",
   "quote": "The laws of the State of Florida govern this Agreement and any dispute arising out of it."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a SaaS subscription between Northwind Labs, Inc. and Orchard Data Ltd. starting 2025-01-01. It runs for three years at $48,000 per year, then auto-renews yearly unless either party gives 60 days' notice. The contract is governed by Florida law and caps liability at fees paid or payable in the prior 12 months."
}
